  &lt;/g&gt;
  &lt;g class=&#34;row dead&#34;&gt;
    &lt;rect class=&#34;card&#34; x=&#34;76&#34; y=&#34;302&#34; width=&#34;286&#34; height=&#34;44&#34; rx=&#34;8&#34; stroke-dasharray=&#34;5 4&#34;/&gt;
