  &lt;a href=&#34;/images/ollama-KAO.png&#34;&gt;
    &lt;img src=&#34;/images/ollama-KAO.png&#34; alt=&#34;查詢天氣：高雄&#34; style=&#34;max-width: 600px;&#34;&gt;
  &lt;/a&gt;
&lt;/div&gt;
